package backend;

import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import org.mindrot.jbcrypt.BCrypt;

@Entity
public class Client {
    //variables
    @Id
    @GeneratedValue(strategy = GenerationType.AUTO)
    private int UserID; 
           //id will be generated by backend
    String FirstName;   //Required
    String LastName;    //Required
    String UserRole;    //Required
    String DOB;         //Required
    String Phone;       //Required
    String Email;       //Optional
    String Pass;        //Required
    String LastLogin;   //Set by functions
    String LastUpdated; //Set by functions
    //empty constructor
    public Client(){}
    //constructor with basic required fields
    public Client(String fn, String ln, String ur, String dob, String p, String pass) {
        FirstName = fn; //set first name
        LastName = ln; //set last name
        UserRole = ur; //set user role
        DOB = dob; //set dob
        Phone = p; //set phone

        //hashing!
        Pass = BCrypt.hashpw(pass, BCrypt.gensalt());
    }
    //constructors with optional field
    public Client(String fn, String ln, String ur, String dob, String p, String e, String pass) {
        FirstName = fn; //set first name
        LastName = ln; //set last name
        UserRole = ur; //set user role
        DOB = dob; //set dob
        Phone = p;     //set z
        Email = e; //set email

        //hasing!
        Pass = BCrypt.hashpw(pass, BCrypt.gensalt());    //set password
    }

    public int getClientID() {
        return UserID;
    }
    public void setClientID(int userID) {
        UserID = uID;
    }
    public getFirstName(){
        return FirstName;
    }
    public setFirstName(String firstName){
        FirstName = firstName;
    }
    public String getLastName(){
        return LastName;
    }
    public void setLastName(String lastName){
        LastName = lastName;
    }
    public String getUserRole(){
        return UserRole;
    }
    public void setUserRole(String userRole){
        UserRole = userRole;
    }
    public String getDOB(){
        return DOB;
    }
    public void setDOB(String dob){
        DOB = dob;
    }
    public String getPhone(){
        return Phone;
    }
    public void setPhone(String phone){
        Phone = phone;
    }
    public String getEmail(){
        return Email;
    }
    public void setEmail(String email){
        Email = email;
    }
    public String getPass(){
        return Pass;
    }
    public void setPass(String pass){
        Pass = pass;
    }
    public String getLastLogin(){
        return LastLogin;
    }
    public void setLastLogin(String lastLogin){
        LastLogin = lastLogin;
    }
    public String getLastUpdated(){
        return LastUpdated;
    }
    public void setLastUpdated(String LastUpdated){
        LastUpdated = lastUpdated;
    }
}

